import { test, expect } from '@playwright/test';

test.describe('Dark Mode Toggle in User Preferences', () => {
  test.beforeEach(async ({ page }) => {
    // Navigate to the application
    await page.goto('/');

    // Login if required (assuming user is already logged in or auto-redirected)
    // If login is needed, uncomment and modify:
    // await page.getByLabel('Email').fill('user@example.com');
    // await page.getByLabel('Password').fill('password');
    // await page.getByRole('button', { name: /sign in/i }).click();

    // Navigate to preferences/settings page
    await page.getByRole('button', { name: /settings|preferences|profile/i }).click();
  });

  test('should toggle dark mode on from preferences', async ({ page }) => {
    // Verify we're on the preferences page
    await expect(page.getByRole('heading', { name: /preferences|settings/i })).toBeVisible();

    // Find and click the dark mode toggle
    const darkModeToggle = page.getByRole('switch', { name: /dark mode|dark theme/i });
    await expect(darkModeToggle).toBeVisible();

    // Get initial state
    const initialState = await darkModeToggle.getAttribute('aria-checked');

    // Toggle dark mode on
    await darkModeToggle.click();

    // Verify the toggle state changed
    const newState = await darkModeToggle.getAttribute('aria-checked');
    expect(newState).not.toBe(initialState);
    expect(newState).toBe('true');

    // Verify visual indication of dark mode (check for dark theme class or styles)
    const htmlElement = page.locator('html');
    const isDarkMode = await htmlElement.evaluate(el => {
      return el.classList.contains('dark') || 
             el.getAttribute('data-theme') === 'dark' ||
             window.getComputedStyle(el).backgroundColor === 'rgb(0, 0, 0)' ||
             document.documentElement.style.colorScheme === 'dark';
    });
    expect(isDarkMode).toBeTruthy();
  });

  test('should toggle dark mode off from preferences', async ({ page }) => {
    // Verify we're on the preferences page
    await expect(page.getByRole('heading', { name: /preferences|settings/i })).toBeVisible();

    // Find the dark mode toggle
    const darkModeToggle = page.getByRole('switch', { name: /dark mode|dark theme/i });
    await expect(darkModeToggle).toBeVisible();

    // Ensure dark mode is on first
    const currentState = await darkModeToggle.getAttribute('aria-checked');
    if (currentState === 'false') {
      await darkModeToggle.click();
    }

    // Toggle dark mode off
    await darkModeToggle.click();

    // Verify the toggle state is now off
    const finalState = await darkModeToggle.getAttribute('aria-checked');
    expect(finalState).toBe('false');

    // Verify visual indication of light mode
    const htmlElement = page.locator('html');
    const isLightMode = await htmlElement.evaluate(el => {
      return !el.classList.contains('dark') && 
             el.getAttribute('data-theme') !== 'dark' &&
             document.documentElement.style.colorScheme !== 'dark';
    });
    expect(isLightMode).toBeTruthy();
  });

  test('should persist dark mode preference after page reload', async ({ page }) => {
    // Verify we're on the preferences page
    await expect(page.getByRole('heading', { name: /preferences|settings/i })).toBeVisible();

    // Find and toggle dark mode
    const darkModeToggle = page.getByRole('switch', { name: /dark mode|dark theme/i });
    await darkModeToggle.click();

    // Verify dark mode is enabled
    await expect(darkModeToggle).toHaveAttribute('aria-checked', 'true');

    // Wait for any save operations to complete
    await page.waitForTimeout(500);

    // Reload the page
    await page.reload();

    // Navigate back to preferences
    await page.getByRole('button', { name: /settings|preferences|profile/i }).click();

    // Verify dark mode preference is still enabled
    const reloadedToggle = page.getByRole('switch', { name: /dark mode|dark theme/i });
    await expect(reloadedToggle).toHaveAttribute('aria-checked', 'true');
  });

  test('should show success message when dark mode preference is saved', async ({ page }) => {
    // Verify we're on the preferences page
    await expect(page.getByRole('heading', { name: /preferences|settings/i })).toBeVisible();

    // Toggle dark mode
    const darkModeToggle = page.getByRole('switch', { name: /dark mode|dark theme/i });
    await darkModeToggle.click();

    // Look for success message or notification
    const successMessage = page.getByText(/saved|updated|preference|success/i);
    await expect(successMessage).toBeVisible({ timeout: 5000 });
  });
});
